solution:
class RangeSum {
  constructor(nums) {
    // prefix[i] = total of the first i numbers; prefix[0] = 0
    this.prefix = new Array(nums.length + 1);
    this.prefix[0] = 0;
    for (let i = 0; i < nums.length; i++) {
      this.prefix[i + 1] = this.prefix[i] + nums[i];
    }
  }

  sum(from, to) {
    return this.prefix[to + 1] - this.prefix[from];
  }
}

tests.code:
const r = new RangeSum([20, 35, 0, 15, 40, 25, 30]);
assertEqual(r.sum(0, 0), 20, 'first day');
assertEqual(r.sum(3, 3), 15, 'one middle day');
assertEqual(r.sum(6, 6), 30, 'last day');

const r = new RangeSum([-2, 0, 3, -5, 2, -1]);
assertEqual(r.sum(0, 2), 1);
assertEqual(r.sum(2, 5), -1);
assertEqual(r.sum(0, 5), -3);

const nums = [];
for (let i = 0; i < 200; i++) nums.push(((i * 31) % 17) - 8);
const r = new RangeSum(nums);
for (let from = 0; from < nums.length; from += 7) {
  for (let to = from; to < nums.length; to += 11) {
    let expected = 0;
    for (let d = from; d <= to; d++) expected += nums[d];
    assertEqual(r.sum(from, to), expected, `sum(${from}, ${to})`);
  }
}
